/**
 * Removes a UNION scope boundary only when its branches can accept every possible incoming row without changing
 * expression inputs, BIND targets, or the result bag.
 *
 * @author Jeen Broekstra
 */
public class UnionScopeChangeOptimizer implements QueryOptimizer {

	private static final Logger logger = LoggerFactory.getLogger(UnionScopeChangeOptimizer.class);

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		if (tupleExpr == null) {
			return;
		}
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr, bindings);
		ArrayDeque<Union> unions = new ArrayDeque<>();
		Set<Union> queued = Collections.newSetFromMap(new IdentityHashMap<>());
		Map<TupleExpr, Boolean> pureRelations = new IdentityHashMap<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				if (union.isVariableScopeChange()) {
					unions.add(union);
					queued.add(union);
				}
				super.meet(union);
			}
		});

		while (!unions.isEmpty()) {
			Union union = unions.removeFirst();
			queued.remove(union);
			if (!union.isVariableScopeChange()) {
				continue;
			}
			TupleExpr pureRegion = pureJoinRegionRoot(union, analysis, pureRelations);
			if (pureRegion == null) {
				CandidateInputs candidateInputs = candidateInputs(union, analysis);
				if (candidateInputs == null || !canAcceptInputs(union, candidateInputs, analysis)) {
					continue;
				}
				union.setVariableScopeChange(false);
				clearBranchScopes(union.getLeftArg(), false);
				clearBranchScopes(union.getRightArg(), false);
			} else {
				clearBranchScopes(pureRegion, true);
			}

			analysis.invalidate(tupleExpr);
			// A retained nested boundary can be the only reason its nearest enclosing UNION was rejected.
			// Each successful removal schedules at most one retry; already pending candidates are not duplicated.
			TupleExpr clearedRoot = pureRegion == null ? union : pureRegion;
			for (QueryModelNode parent = clearedRoot.getParentNode(); parent != null; parent = parent.getParentNode()) {
				if (parent instanceof Union enclosing && enclosing.isVariableScopeChange()) {
					if (queued.add(enclosing)) {
						unions.addLast(enclosing);
					}
					break;
				}
			}
		}
	}

	private TupleExpr pureJoinRegionRoot(Union union, QueryAlgebraBindingAnalysis analysis,
			Map<TupleExpr, Boolean> pureRelations) {
		if (!hasOrdinaryJoinParent(union) || !analysis.contextAt(union).bindingDomainKnown()
				|| !AlgebraEvaluationSafety.isPureRelational(union, pureRelations)) {
			return null;
		}
		// Clear a containing pure Join as well: otherwise normalization can copy its marker onto a new UNION.
		// The highest removed boundary must still be an ordinary Join operand. In particular, clearing an
		// OPTIONAL's direct right operand requires the separate containing-operator proof below.
		TupleExpr region = union;
		while (region.getParentNode() instanceof Join parent && parent.getClass() == Join.class
				&& hasOrdinaryJoinParent(parent) && analysis.contextAt(parent).bindingDomainKnown()
				&& AlgebraEvaluationSafety.isPureRelational(parent, pureRelations)) {
			region = parent;
		}
		return region;
	}

	private boolean hasOrdinaryJoinParent(QueryModelNode node) {
		return node.getParentNode() != null && node.getParentNode().getClass() == Join.class;
	}

	private CandidateInputs candidateInputs(Union union, QueryAlgebraBindingAnalysis analysis) {
		Set<String> possibleSiblingInputs = new HashSet<>();
		Set<String> overwrittenSiblingInputs = new HashSet<>();
		Set<String> optionalInheritedInputs = new HashSet<>();
		LeftJoin containingOptional = directOptionalParent(union);
		ReadOnlyContext unionInput = analysis.contextAt(union);
		if (!unionInput.bindingDomainKnown()) {
			reject("unknown input domain", union);
			return null;
		}
		QueryModelNode current = union;
		while (current.getParentNode() != null) {
			QueryModelNode parent = current.getParentNode();
			TupleExpr sibling = null;
			if (parent.getClass() == Join.class) {
				Join join = (Join) parent;
				sibling = current == join.getLeftArg() ? join.getRightArg() : join.getLeftArg();
			} else if (parent.getClass() == LeftJoin.class) {
				LeftJoin optional = (LeftJoin) parent;
				// OPTIONAL's left rows may feed its right operand, never the other way around.
				if (current == optional.getRightArg()) {
					sibling = optional.getLeftArg();
				}
			} else if (!(parent.getClass() == Union.class
					|| parent.getClass() == Filter.class && current == ((Filter) parent).getArg()
					|| parent.getClass() == Extension.class && current == ((Extension) parent).getArg()
					|| parent.getClass() == Projection.class && current == ((Projection) parent).getArg()
					|| parent.getClass() == Distinct.class && current == ((Distinct) parent).getArg()
					|| parent.getClass() == Reduced.class && current == ((Reduced) parent).getArg()
					|| parent.getClass() == Order.class && current == ((Order) parent).getArg()
					|| parent.getClass() == Slice.class && current == ((Slice) parent).getArg()
					|| parent.getClass() == Group.class && current == ((Group) parent).getArg()
					|| parent.getClass() == QueryRoot.class)) {
				if (hasJoinAncestor(parent)) {
					reject("unsupported ancestor input transition", parent);
					return null;
				}
				break;
			}
			// These are a conservative envelope of MAY inputs across modeled evaluator transitions, including
			// possible later reorderings. A UNION's other arm and an Extension's own targets are not suppliers.
			// Only the tuple-input edge is modeled for modifiers; their output names are not additional suppliers.
			// Independent operands can retain invocation inputs, so a lexical marker alone is not a stop rule.
			if (sibling != null) {
				ReadOnlyContext siblingInput = analysis.contextAt(sibling);
				OutputFacts siblingFacts = analysis.outputFacts(sibling, siblingInput);
				if (!siblingFacts.possibleOutputsKnown()) {
					reject("unknown sibling outputs", sibling);
					return null;
				}
				possibleSiblingInputs.addAll(siblingFacts.possibleOutputs());
				overwrittenSiblingInputs.addAll(siblingFacts.overwrittenInputNames());
				if (containingOptional != null && parent != containingOptional) {
					optionalInheritedInputs.addAll(siblingFacts.possibleOutputs());
				}
			}
			current = parent;
		}

		Set<String> allInputs = new HashSet<>(possibleSiblingInputs);
		allInputs.addAll(unionInput.visibleNames());
		allInputs.addAll(unionInput.externalGuaranteedNames());
		return new CandidateInputs(possibleSiblingInputs, allInputs, overwrittenSiblingInputs, optionalInheritedInputs,
				unionInput);
	}

	private LeftJoin directOptionalParent(Union union) {
		return union.getParentNode() != null && union.getParentNode().getClass() == LeftJoin.class
				&& ((LeftJoin) union.getParentNode()).getRightArg() == union
						? (LeftJoin) union.getParentNode()
						: null;
	}

	private boolean hasJoinAncestor(QueryModelNode node) {
		for (QueryModelNode current = node; current != null; current = current.getParentNode()) {
			if (current instanceof Join) {
				return true;
			}
		}
		return false;
	}

	private boolean canAcceptInputs(Union union, CandidateInputs candidateInputs,
			QueryAlgebraBindingAnalysis sourceAnalysis) {
		if (!supportsInputPropagation(union.getLeftArg(), candidateInputs.allInputNames)
				|| !supportsInputPropagation(union.getRightArg(), candidateInputs.allInputNames)) {
			return false;
		}
		if (!AlgebraEvaluationSafety.isRepeatable(union.getLeftArg())
				|| !AlgebraEvaluationSafety.isRepeatable(union.getRightArg())) {
			return reject("nonrepeatable branch", union);
		}

		LeftJoin optional = directOptionalParent(union);
		if (optional != null && optional.hasCondition()
				&& !AlgebraEvaluationSafety.isRepeatable(optional.getCondition())) {
			// Removing a directly attached boundary can select OPTIONAL's prefilter path, changing the number
			// of condition evaluations even when all binding facts remain equal.
			return reject("nonrepeatable enclosing OPTIONAL condition", optional.getCondition());
		}
		LeftJoin candidateOptional = optional == null ? null : optional.clone();
		Union candidateUnion = candidateOptional == null ? union.clone() : (Union) candidateOptional.getRightArg();
		candidateUnion.setVariableScopeChange(false);
		clearBranchScopes(candidateUnion.getLeftArg(), false);
		clearBranchScopes(candidateUnion.getRightArg(), false);
		ReadOnlyContext candidateInput = candidateInputs.unionInput;
		QueryAlgebraBindingAnalysis branchSourceAnalysis = sourceAnalysis;
		if (optional != null) {
			ReadOnlyContext optionalInput = sourceAnalysis.contextAt(optional);
			// Left-produced names belong only at the right entry, not in the OPTIONAL's own inherited input.
			branchSourceAnalysis = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(optional,
					optionalInput, candidateInputs.optionalInheritedInputs);
			QueryAlgebraBindingAnalysis optionalAnalysis = QueryAlgebraBindingAnalysis
					.withInputContextAndPossibleInputs(candidateOptional, optionalInput,
							candidateInputs.optionalInheritedInputs);
			if (!sameInputFrame(branchSourceAnalysis.contextAt(optional.getLeftArg()),
					optionalAnalysis.contextAt(candidateOptional.getLeftArg()), optionalAnalysis)
					|| optional.hasCondition()
							&& !sameInputFrame(branchSourceAnalysis.contextAt(optional.getCondition()),
									optionalAnalysis.contextAt(candidateOptional.getCondition()), optionalAnalysis)) {
				return reject("changed enclosing OPTIONAL input frame", optional);
			}
			candidateInput = optionalAnalysis.contextAt(candidateUnion);
		}
		QueryAlgebraBindingAnalysis candidateAnalysis = QueryAlgebraBindingAnalysis
				.withInputContextAndPossibleInputs(candidateUnion, candidateInput,
						candidateInputs.possibleSiblingInputs);

		return expressionFramesStable(union.getLeftArg(), candidateUnion.getLeftArg(), branchSourceAnalysis,
				candidateAnalysis,
				candidateInputs)
				&& expressionFramesStable(union.getRightArg(), candidateUnion.getRightArg(), branchSourceAnalysis,
						candidateAnalysis, candidateInputs);
	}

	private boolean sameInputFrame(ReadOnlyContext source, ReadOnlyContext candidate,
			QueryAlgebraBindingAnalysis analysis) {
		if (!source.bindingDomainKnown() || !candidate.bindingDomainKnown()) {
			return false;
		}
		Set<String> names = new HashSet<>(source.visibleNames());
		names.addAll(source.maybeBoundNames());
		names.addAll(source.guaranteedNames());
		names.addAll(candidate.visibleNames());
		names.addAll(candidate.maybeBoundNames());
		names.addAll(candidate.guaranteedNames());
		return analysis.bindingFactsEquivalent(names, source, candidate)
				&& source.externalValues().equals(candidate.externalValues())
				&& source.externalGuaranteedNames().equals(candidate.externalGuaranteedNames());
	}

	private boolean expressionFramesStable(TupleExpr sourceBranch, TupleExpr candidateBranch,
			QueryAlgebraBindingAnalysis sourceAnalysis, QueryAlgebraBindingAnalysis candidateAnalysis,
			CandidateInputs candidateInputs) {
		List<ExpressionPoint> sourcePoints = expressionPoints(sourceBranch, sourceAnalysis);
		List<ExpressionPoint> candidatePoints = expressionPoints(candidateBranch, candidateAnalysis);
		if (sourcePoints == null || candidatePoints == null || sourcePoints.size() != candidatePoints.size()) {
			return reject("unsupported expression input transition", sourceBranch);
		}
		for (int i = 0; i < sourcePoints.size(); i++) {
			ExpressionPoint source = sourcePoints.get(i);
			ExpressionPoint candidate = candidatePoints.get(i);
			if (source.expression.getClass() != candidate.expression.getClass()
					|| !AlgebraEvaluationSafety.isRepeatable(source.expression)) {
				return reject("changed or nonrepeatable expression", source.expression);
			}
			Set<String> possibleInputs = new HashSet<>(candidateInputs.allInputNames);
			possibleInputs.addAll(candidateInputs.possibleSiblingInputs);
			possibleInputs.addAll(source.crossedSiblingInputs);
			possibleInputs.addAll(candidate.crossedSiblingInputs);
			Set<String> overwrittenInputs = new HashSet<>(candidateInputs.overwrittenSiblingInputs);
			overwrittenInputs.addAll(source.crossedOverwrittenInputs);
			overwrittenInputs.addAll(candidate.crossedOverwrittenInputs);
			if (source.target != null && (!source.target.equals(candidate.target)
					|| candidateInputs.allInputNames.contains(source.target)
					|| possibleInputs.contains(source.target))) {
				return reject("BIND target collides with possible input", source.expression, source.target);
			}

			Dependencies sourceDependencies = sourceAnalysis.dependencies(source.expression, source.input);
			Dependencies candidateDependencies = candidateAnalysis.dependencies(candidate.expression, candidate.input);
			if (!sourceDependencies.directReferences().equals(candidateDependencies.directReferences())
					|| !sourceDependencies.correlatedInputs().equals(candidateDependencies.correlatedInputs())
					|| !sourceDependencies.existsLocals().equals(candidateDependencies.existsLocals())) {
				return reject("changed expression dependencies", source.expression);
			}
			Set<String> injectedNames = new HashSet<>(possibleInputs);
			injectedNames.addAll(overwrittenInputs);
			if (sourceDependencies.existsLocals().stream().anyMatch(injectedNames::contains)) {
				return reject("possible input reaches an EXISTS local", source.expression);
			}
			Set<String> references = new HashSet<>(sourceDependencies.directReferences());
			references.addAll(sourceDependencies.correlatedInputs());
			if (!candidateAnalysis.bindingFactsStableAt(references, source.input, candidate.input,
					possibleInputs, overwrittenInputs)) {
				return reject("unstable expression binding facts", source.expression);
			}
		}
		return true;
	}

	private List<ExpressionPoint> expressionPoints(TupleExpr branch, QueryAlgebraBindingAnalysis analysis) {
		List<ExpressionPoint> points = new ArrayList<>();
		boolean[] inputsKnown = { true };
		analysis.visitScoped(branch, analysis.contextAt(branch), (node, input) -> {
			if (node instanceof Projection projection && projection.isSubquery()) {
				return false;
			}
			if (node instanceof SubQueryValueOperator) {
				return false;
			}
			CrossedInputs crossedInputs = crossedSiblingInputs(node, branch, analysis);
			if (crossedInputs == null) {
				inputsKnown[0] = false;
				return false;
			}
			if (node instanceof Projection projection && !projection.isSubquery()
					&& (!crossedInputs.possibleInputs.isEmpty()
							|| !crossedInputs.overwrittenInputs.isEmpty())) {
				// A non-subquery Projection can fall back to parent bindings for an unavailable projection source.
				// A branch-local sibling would therefore become visible to it when the marked scope is removed.
				inputsKnown[0] = false;
				return false;
			}
			if (node instanceof Filter filter) {
				ReadOnlyContext expressionInput = analysis.childInput(filter, filter.getCondition(), input);
				points.add(new ExpressionPoint(filter.getCondition(), expressionInput, null,
						crossedInputs.possibleInputs, crossedInputs.overwrittenInputs));
			}
			if (node instanceof ExtensionElem element) {
				points.add(new ExpressionPoint(element.getExpr(), input, element.getName(),
						crossedInputs.possibleInputs, crossedInputs.overwrittenInputs));
			}
			return true;
		});
		return inputsKnown[0] ? points : null;
	}

	private CrossedInputs crossedSiblingInputs(QueryModelNode owner, TupleExpr branch,
			QueryAlgebraBindingAnalysis analysis) {
		Set<String> possibleInputs = new HashSet<>();
		Set<String> overwrittenInputs = new HashSet<>();
		QueryModelNode current = owner;
		while (current != branch) {
			QueryModelNode parent = current.getParentNode();
			if (parent == null) {
				return null;
			}
			if (parent instanceof Join join) {
				TupleExpr sibling;
				if (current == join.getLeftArg()) {
					sibling = join.getRightArg();
				} else if (current == join.getRightArg()) {
					sibling = join.getLeftArg();
				} else {
					return null;
				}
				OutputFacts siblingFacts = analysis.outputFacts(sibling, analysis.contextAt(sibling));
				if (!siblingFacts.possibleOutputsKnown()) {
					return null;
				}
				possibleInputs.addAll(siblingFacts.possibleOutputs());
				overwrittenInputs.addAll(siblingFacts.overwrittenInputNames());
			}
			current = parent;
		}
		return new CrossedInputs(possibleInputs, overwrittenInputs);
	}

	private boolean supportsInputPropagation(TupleExpr expression, Set<String> possibleInputs) {
		Class<?> type = expression.getClass();
		if (type == StatementPattern.class || type == SingletonSet.class || type == BindingSetAssignment.class) {
			return true;
		}
		if (type == QueryRoot.class) {
			return supportsInputPropagation(((QueryRoot) expression).getArg(), possibleInputs);
		}
		if (type == Join.class) {
			Join join = (Join) expression;
			return supportsInputPropagation(join.getLeftArg(), possibleInputs)
					&& supportsInputPropagation(join.getRightArg(), possibleInputs);
		}
		if (type == Union.class) {
			Union nestedUnion = (Union) expression;
			if (nestedUnion.isVariableScopeChange()) {
				return reject("nested UNION scope still required", nestedUnion);
			}
			return supportsInputPropagation(nestedUnion.getLeftArg(), possibleInputs)
					&& supportsInputPropagation(nestedUnion.getRightArg(), possibleInputs);
		}
		if (type == Filter.class) {
			Filter filter = (Filter) expression;
			if (!AlgebraEvaluationSafety.isRepeatable(filter.getCondition())) {
				return reject("nonrepeatable filter", filter.getCondition());
			}
			return supportsInputPropagation(filter.getArg(), possibleInputs);
		}
		if (type == Extension.class) {
			Extension extension = (Extension) expression;
			for (ExtensionElem element : extension.getElements()) {
				if (!AlgebraEvaluationSafety.isRepeatable(element.getExpr())) {
					return reject("nonrepeatable extension", element);
				}
				if (possibleInputs.contains(element.getName())) {
					return reject("BIND target collides with possible input", element, element.getName());
				}
			}
			return supportsInputPropagation(extension.getArg(), possibleInputs);
		}
		if (type == Projection.class) {
			Projection projection = (Projection) expression;
			if (!possibleInputs.isEmpty()) {
				return reject("projection with possible inputs", projection);
			}
			return AlgebraEvaluationSafety.isRepeatable(projection)
					&& (projection.isSubquery()
							|| supportsInputPropagation(projection.getArg(), possibleInputs));
		}
		return reject("unsupported branch operator", expression);
	}

	private void clearBranchScopes(TupleExpr branch, boolean pureRegion) {
		branch.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof Projection projection && projection.isSubquery()) {
					return;
				}
				if (!pureRegion && node instanceof Union nestedUnion && nestedUnion.isVariableScopeChange()) {
					return;
				}
				if (node instanceof SubQueryValueOperator) {
					return;
				}
				if (node instanceof VariableScopeChange scopeChange) {
					scopeChange.setVariableScopeChange(false);
				}
				super.meetNode(node);
			}
		});
	}

	private boolean reject(String reason, QueryModelNode node) {
		return reject(reason, node, null);
	}

	private boolean reject(String reason, QueryModelNode node, String bindingName) {
		if (logger.isDebugEnabled()) {
			if (bindingName == null) {
				logger.debug("Retaining UNION scope: {} at {}", reason, node.getClass().getSimpleName());
			} else {
				logger.debug("Retaining UNION scope: {} at {} (binding {})", reason, node.getClass().getSimpleName(),
						bindingName);
			}
		}
		return false;
	}

	private record CandidateInputs(Set<String> possibleSiblingInputs, Set<String> allInputNames,
			Set<String> overwrittenSiblingInputs, Set<String> optionalInheritedInputs, ReadOnlyContext unionInput) {
		private CandidateInputs {
			possibleSiblingInputs = Set.copyOf(possibleSiblingInputs);
			allInputNames = Set.copyOf(allInputNames);
			overwrittenSiblingInputs = Set.copyOf(overwrittenSiblingInputs);
			optionalInheritedInputs = Set.copyOf(optionalInheritedInputs);
		}
	}

	private record CrossedInputs(Set<String> possibleInputs, Set<String> overwrittenInputs) {
		private CrossedInputs {
			possibleInputs = Set.copyOf(possibleInputs);
			overwrittenInputs = Set.copyOf(overwrittenInputs);
		}
	}

	private record ExpressionPoint(ValueExpr expression, ReadOnlyContext input, String target,
			Set<String> crossedSiblingInputs, Set<String> crossedOverwrittenInputs) {
	}
}
